CREATE TYPE "public"."sv_entity_kind" AS ENUM ('MASTER_BRAND', 'SUBBRAND', 'CONCEPT', 'LOCATION_BRAND');
CREATE TYPE "public"."sv_parent_relation" AS ENUM ('SUBBRAND_OF', 'CONCEPT_WITHIN', 'LOCATION_OF', 'UNSPECIFIED');
CREATE TYPE "public"."sv_entity_confirmation" AS ENUM ('PROPOSED', 'CLIENT_CONFIRMED', 'ANALYST_CONFIRMED', 'REJECTED');
CREATE TYPE "public"."sv_geo_precision" AS ENUM ('CITY', 'ADDRESS', 'COORDINATE', 'UNKNOWN');
CREATE TYPE "public"."sv_reference_origin" AS ENUM ('USER_PROVIDED', 'PUBLIC_SITE', 'ANALYST_ENTERED');
CREATE TYPE "public"."sv_location_role" AS ENUM ('PRIMARY', 'SECONDARY', 'WITHIN');
CREATE TYPE "public"."sv_location_confirmation" AS ENUM ('PROPOSED', 'CONFIRMED', 'REJECTED');
CREATE TABLE "sv_entities" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "project_id" uuid NOT NULL REFERENCES "sv_projects"("id"), "parent_entity_id" uuid REFERENCES "sv_entities"("id"), "entity_kind" "sv_entity_kind" NOT NULL, "parent_relation" "sv_parent_relation", "confirmation_status" "sv_entity_confirmation" DEFAULT 'PROPOSED' NOT NULL, "name" text NOT NULL, "aliases" text[] DEFAULT '{}' NOT NULL, "prelaunch" boolean DEFAULT false NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_business_locations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "entity_id" uuid NOT NULL REFERENCES "sv_entities"("id"), "display_name" text NOT NULL, "country_code" text NOT NULL, "admin_area" text, "locality" text, "address_text" text, "timezone" text, "latitude" numeric(9,6), "longitude" numeric(9,6), "geo_precision" "sv_geo_precision" DEFAULT 'UNKNOWN' NOT NULL, "google_maps_url_reference" text, "google_place_id_reference" text, "reference_origin" "sv_reference_origin" DEFAULT 'USER_PROVIDED' NOT NULL, "location_role" "sv_location_role" DEFAULT 'PRIMARY' NOT NULL, "confirmation_status" "sv_location_confirmation" DEFAULT 'PROPOSED' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "sv_entities_org_project_idx" ON "sv_entities" ("organization_id", "project_id"); CREATE INDEX "sv_business_locations_entity_idx" ON "sv_business_locations" ("entity_id"); CREATE INDEX "sv_business_locations_org_idx" ON "sv_business_locations" ("organization_id");
ALTER TABLE "sv_entities" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_business_locations" ENABLE ROW LEVEL SECURITY;
